toolScript:
const dropZone = document.getElementById('drop-zone');
        const fileInput = document.getElementById('file-input');
        const resultsPanel = document.getElementById('results-panel');
        const lufsVal = document.getElementById('lufs-val');
        const statusBadge = document.getElementById('status-badge');
        const lufsBar = document.getElementById('lufs-bar');
        const peakVal = document.getElementById('peak-val');
        const spotifyVal = document.getElementById('spotify-val');
        const youtubeVal = document.getElementById('youtube-val');
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-pink-400' : (type === 'error' ? 'text-red-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        // Drag & Drop
        dropZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropZone.classList.add('drag-over');
        });
        dropZone.addEventListener('dragleave', () => {
            dropZone.classList.remove('drag-over');
        });
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('drag-over');
            if (e.dataTransfer.files.length) {
                handleFile(e.dataTransfer.files[0]);
            }
        });
        fileInput.addEventListener('change', (e) => {
            if (e.target.files.length) {
                handleFile(e.target.files[0]);
            }
        });
        async function handleFile(file) {
            log(`Processing: ${file.name} (${(file.size / 1024 / 1024).toFixed(1)}MB)`);
            resultsPanel.style.display = 'none';
            try {
                const arrayBuffer = await file.arrayBuffer();
                const audioContext = new (window.AudioContext || window.webkitAudioContext)();
                log("Decoding audio data... (This may take a moment)");
                const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
                log("Processing K-Weighted filter chain...");
                const result = await calculateLUFS(audioBuffer);
                displayResults(result);
                log("Analysis Complete.", "success");
            } catch (err) {
                console.error(err);
                log("ERROR: Could not decode audio file.", "error");
            }
        }
        async function calculateLUFS(buffer) {
            // Offline Context for fast processing
            const offlineCtx = new OfflineAudioContext(buffer.numberOfChannels, buffer.length, buffer.sampleRate);
            const source = offlineCtx.createBufferSource();
            source.buffer = buffer;
            // K-Weighting Filters (ITU-R BS.1770-4)
            // Stage 1: High Shelving
            const highShelf = offlineCtx.createBiquadFilter();
            highShelf.type = "highshelf";
            highShelf.frequency.value = 1500;
            highShelf.gain.value = 4; // dB
            // Stage 2: High Pass (RLB)
            const highPass = offlineCtx.createBiquadFilter();
            highPass.type = "highpass";
            highPass.frequency.value = 38;
            highPass.Q.value = 0.5;
            source.connect(highShelf);
            highShelf.connect(highPass);
            highPass.connect(offlineCtx.destination);
            source.start(0);
            const renderedBuffer = await offlineCtx.startRendering();
            // Calculate Integrated Loudness
            let sum = 0;
            const channels = renderedBuffer.numberOfChannels;
            for (let c = 0; c < channels; c++) {
                const data = renderedBuffer.getChannelData(c);
                let channelSum = 0;
                // Calculate Mean Square
                for (let i = 0; i < data.length; i++) {
                    channelSum += data[i] * data[i];
                }
                sum += channelSum / data.length;
            }
            // Formula: -0.691 + 10 * log10(sum)
            const lufs = -0.691 + 10 * Math.log10(sum);
            // True Peak (Approximate) from original buffer
            let maxPeak = 0;
            for (let c = 0; c < buffer.numberOfChannels; c++) {
                const data = buffer.getChannelData(c);
                for (let i = 0; i < data.length; i++) {
                    const abs = Math.abs(data[i]);
                    if (abs > maxPeak) maxPeak = abs;
                }
            }
            const dBTP = 20 * Math.log10(maxPeak);
            return { lufs, dBTP };
        }
        function displayResults(data) {
            resultsPanel.style.display = 'block';
            const lufsRounded = data.lufs.toFixed(1);
            lufsVal.innerText = lufsRounded;
            peakVal.innerText = `${data.dBTP.toFixed(2)} dBTP`;
            // Status Logic
            let status = "PERFECT";
            let colorClass = "status-good";
            if (data.lufs > -13) {
                status = "TOO LOUD (WILL BE PENALIZED)";
                colorClass = "status-bad";
            } else if (data.lufs < -16) {
                status = "TOO QUIET (WILL BE BOOSTED)";
                colorClass = "status-warn";
            }
            statusBadge.innerText = status;
            statusBadge.className = `status-badge ${colorClass}`;
            const percentage = Math.max(0, Math.min(100, (60 + data.lufs) / 60 * 100));
            lufsBar.style.width = `${percentage}%`;
            const spotifyDiff = -14 - data.lufs;
            if (Math.abs(spotifyDiff) < 1) spotifyVal.innerText = "No Change";
            else if (spotifyDiff > 0) spotifyVal.innerText = `+${spotifyDiff.toFixed(1)} dB (Boost)`;
            else spotifyVal.innerText = `${spotifyDiff.toFixed(1)} dB (Reduction)`;
            if (data.lufs > -14) youtubeVal.innerText = "Penalty Active";
            else youtubeVal.innerText = "Safe";
        }

        log("Analyzer Engine initialized. Ready for file.");
